<script setup lang="ts">
// FR-AUDIT-001 / D18-API-042,043 / TC-AUDIT-001,005,006
import {ref,reactive,onMounted} from 'vue';import {get,command,errorText,type Row,type Page} from '../../api/implemented';import {useAuthStore} from '../../stores/auth';
const auth=useAuthStore(),result=ref<Page|null>(null),selected=ref<Row|null>(null),error=ref(''),notice=ref(''),busy=ref(false),page=ref(1),write=command();const filters=reactive({kind:'BUSINESS',orgId:'',objectType:'',objectId:'',actorId:'',action:'',outcome:'',traceId:'',from:'',to:''});let applied:Record<string,string>={kind:'BUSINESS'};
function query(){const q:Record<string,string>={};for(const [k,v] of Object.entries(filters))if(v.trim()&&(filters.kind!=='SECURITY'||!['objectType','objectId'].includes(k)))q[k]=['from','to'].includes(k)?new Date(v).toISOString():v.trim();return q}
async function load(p=1,refresh=true){busy.value=true;error.value='';selected.value=null;try{if(refresh)applied=query();result.value=await get<Page>('D18-API-042',{}, {...applied,page:String(p),size:'20'});page.value=p}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function download(){busy.value=true;error.value='';notice.value='';try{const x=await write<{text:string;filename:string;rowCount:number;truncated:boolean}>('D18-API-043',{}, {filters:query(),limit:2000});const url=URL.createObjectURL(new Blob([x.text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=x.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value=`已导出 ${x.rowCount} 条记录${x.truncated?'，超过2000条的记录已截断，请缩小范围后导出':'。'}`}catch(e){error.value=errorText(e)}finally{busy.value=false}}
onMounted(()=>load());
</script>
<template><section><div class="hero"><div><span class="eyebrow">GOVERNANCE AUDIT TRAIL</span><h2>审计日志</h2><p>查询授权组织的业务变更和安全事件，追踪每一次治理动作。</p></div><span class="badge">只读审计</span></div><form @submit.prevent="load()"><div class="filters"><label>日志类型<select v-model="filters.kind"><option value="BUSINESS">业务审计</option><option value="SECURITY">安全事件</option></select></label><label>组织编号<input v-model="filters.orgId" placeholder="全部授权组织"></label><label>执行人编号<input v-model="filters.actorId" inputmode="numeric"></label><label>动作<input v-model="filters.action" placeholder="例如 ASSET_PUBLISH"></label><label>结果<select v-model="filters.outcome"><option value="">全部</option><option value="SUCCESS">成功</option><option value="DENIED">拒绝</option><option value="ERROR">异常</option></select></label><label>追踪号<input v-model="filters.traceId" maxlength="64"></label><label v-if="filters.kind==='BUSINESS'">业务对象类型<input v-model="filters.objectType"></label><label v-if="filters.kind==='BUSINESS'">业务对象编号<input v-model="filters.objectId" inputmode="numeric"></label><label>起始时间<input type="datetime-local" v-model="filters.from"></label><label>截止时间<input type="datetime-local" v-model="filters.to"></label></div><div class="actions"><button :disabled="busy">{{busy?'处理中…':'查询日志'}}</button><button v-if="auth.permissions.includes('audit:export')" type="button" :disabled="busy" @click="download">导出CSV</button><span class="muted">默认近30天，最长366天；导出最多2000条。</span></div></form><p class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="result"><table><thead><tr><th>时间</th><th>执行人</th><th>动作</th><th>对象</th><th>结果</th><th>追踪号</th><th>详情</th></tr></thead><tbody><tr v-for="r in result.items" :key="r.id"><td>{{r.createdAt}}</td><td>{{r.actorId||'未识别'}}</td><td>{{r.action}}</td><td>{{r.objectType||r.objectRef}} {{r.objectId}}</td><td>{{r.outcome}}</td><td>{{r.traceId}}</td><td><button @click="selected=r">查看</button></td></tr></tbody></table><p v-if="!result.total" class="muted">当前条件下没有可见记录。</p><div class="actions"><button :disabled="busy||page===1" @click="load(page-1,false)">上一页</button><span>共 {{result.total}} 条 · 第 {{page}} 页</span><button :disabled="busy||page*20>=result.total" @click="load(page+1,false)">下一页</button></div></template><article v-if="selected"><div class="actions"><h3>审计详情</h3><button @click="selected=null">收起</button></div><p>动作 {{selected.action}} · 组织 {{selected.orgId}} · 追踪号 {{selected.traceId}}</p><p v-if="selected.reason">说明：{{selected.reason}}</p><div class="columns" v-if="selected.kind==='BUSINESS'"><div><h3>变更前</h3><pre>{{JSON.stringify(selected.beforeJson,null,2)||'无'}}</pre></div><div><h3>变更后</h3><pre>{{JSON.stringify(selected.afterJson,null,2)||'无'}}</pre></div></div><pre v-else>{{JSON.stringify(selected.details,null,2)||'无'}}</pre><RouterLink v-if="selected.objectType==='governance_work_order'&&auth.permissions.includes('workorder:read')" :to="'/workorders?order='+selected.objectId">打开关联工单</RouterLink></article></section></template>
